const calls=[],stack=[];
const canvas=new Proxy({globalAlpha:1,lineWidth:1,save(){stack.push({globalAlpha:this.globalAlpha,lineWidth:this.lineWidth});calls.push(['save']);},restore(){Object.assign(this,stack.pop());calls.push(['restore']);},createRadialGradient(){return{addColorStop(){}};},isPointInPath(){return false;},isPointInStroke(){return false;},measureText(){return{width:20};}}, {get:(o,k)=>k in o?o[k]:(...a)=>calls.push([k,...a]),set:(o,k,v)=>(o[k]=v,true)});
class Element{
  constructor(tag='div'){this.tagName=tag.toUpperCase();this.dataset={};this.style={setProperty(){}};this.classList={add(){},remove(){},toggle(){},contains(){return false;}};this.children=[];this._html='';this.value='';}
  set innerHTML(v){this._html=v;this.children=[];for(const match of v.matchAll(/<(input|button|select)\b([^>]*)>/g)){const n=new Element(match[1]);for(const a of match[2].matchAll(/([\w-]+)(?:="([^"]*)")?/g)){const key=a[1],value=a[2]||'';if(key.startsWith('data-'))n.dataset[key.slice(5).replace(/-([a-z])/g,(_,c)=>c.toUpperCase())]=value;else n[key]=value;}n.checked=/\bchecked\b/.test(match[2]);this.children.push(n);}}
  get innerHTML(){return this._html;}
  contains(){return false;}blur(){}focus(){}select(){}appendChild(n){this.children.push(n);}remove(){}addEventListener(){}setPointerCapture(){}getContext(){return canvas;}getBoundingClientRect(){return{width:800,height:600,left:0,top:0};}
  querySelectorAll(s){const m=s.match(/^\[data-([\w-]+)(?:="([^"]*)")?\]$/);if(!m)return[];const k=m[1].replace(/-([a-z])/g,(_,c)=>c.toUpperCase());return this.children.filter(n=>k in n.dataset&&(m[2]===undefined||n.dataset[k]===m[2]));}
  querySelector(s){return this.querySelectorAll(s)[0]||null;}
}
const nodes=new Map(),element=s=>{if(!nodes.has(s))nodes.set(s,new Element());return nodes.get(s);},errors=[];
const ctx={window:{addEventListener(){},devicePixelRatio:1},document:{activeElement:null,querySelector:element,querySelectorAll:()=>[],createElement:t=>new Element(t),body:new Element(),documentElement:new Element(),addEventListener(){}},Path2D:class{moveTo(){}lineTo(){}bezierCurveTo(){}closePath(){}},console:{...console,error:e=>errors.push(e.message)},performance,Blob,TextEncoder,TextDecoder,URL,Float32Array,Uint8Array,Uint32Array,DataView,ArrayBuffer,Set,Map,localStorage:{getItem(){return null;},setItem(){}},requestAnimationFrame:()=>0,cancelAnimationFrame(){},setTimeout:()=>0,clearTimeout(){},setInterval(){}};
vm.createContext(ctx);vm.runInContext(code,ctx,{timeout:5000});const A=ctx.window.test,defaults=JSON.stringify(A.VEC),styleDefaults=JSON.stringify(A.S.newStyle);let passed=0;
function reset(){Object.assign(A.VEC,JSON.parse(defaults));A.S.newStyle=JSON.parse(styleDefaults);A.S.doc=A.newDoc();A.S.frame=0;A.S.mode='setup';A.S.tool='points';A.S.camSel=false;A.S.selPts=new Set();A.S.selLayers=[];A.S.selKeys=new Set();A.S.selBones=new Set();A.S.selBone=null;A.S.selShape=null;A.S.autoKey=true;A.S.media={};A.S.view={zoom:1,panX:0,panY:0};A.H.undo=[];A.H.redo=[];A.H.pending=null;A.Stage.cv={width:800,height:600,style:{},getBoundingClientRect:()=>({width:800,height:600})};A.Stage.ctx=canvas;A.Stage.rec=[];A.Stage.drag=null;A.Stage.pen=null;A.Stage.preview=null;A.Stage.mouse=[0,0];A.Stage.dpr=1;A.TL.pins.clear();A.TL.contextKey='';calls.length=0;errors.length=0;stack.length=0;canvas.globalAlpha=1;}
function layer(type='vector'){const L=A.mkLayer(type,'Drawing');A.S.doc.layers.push(L);A.S.selLayers=[L.id];return L;}
function path(L,coords,closed=false){return A.vectorAddPath(L,coords,closed);}
function near(a,b,t=1e-7){assert.ok(Math.abs(a-b)<t,`${a} != ${b}`);}
