function down(tool,x,y,e=event()){A.S.tool=tool;A.Stage.mouse=[x,y];A.TOOLS[tool].down(e,x,y);}
function move(tool,x,y,e=event()){A.Stage.mouse=[x,y];if(A.Stage.drag)A.Stage.drag.moved=true;A.TOOLS[tool].move(e,x,y);}
function up(tool,e=event()){A.TOOLS[tool].up(e);A.Stage.drag=null;A.Stage.preview=null;}
