function test(name,fn){reset();try{fn();assert.equal(errors.length,0);passed++;console.log('PASS',name);}catch(e){console.error('FAIL',name);throw e;}}

test('all 26 vector tools (including the Eyedropper) are registered with independent options',()=>{assert.equal(A.VECTOR_DRAW.length+A.VECTOR_FILL.length,26);for(const id of [...A.VECTOR_DRAW,...A.VECTOR_FILL]){assert.equal(typeof A.TOOLS[id].down,'function');if(id!=='fill'){assert.equal(typeof A.TOOLS[id].move,'function',id);assert.equal(typeof A.TOOLS[id].up,'function',id);}A.S.tool=id;assert.ok(A.vectorOptionsHTML(null).length>20);}assert.equal(new Set(A.TOOL_GROUPS.flatMap(g=>g[1])).size,A.TOOL_GROUPS.flatMap(g=>g[1]).length);});
test('layer context and ancestor locks protect every vector tool',()=>{const G=layer('bone'),L=A.mkLayer('vector');G.children=[L];A.S.selLayers=[G.id];for(const id of [...A.VECTOR_DRAW,...A.VECTOR_FILL])assert.ok(A.toolAvail(id));A.S.selLayers=[L.id];G.lock=true;for(const id of [...A.VECTOR_DRAW,...A.VECTOR_FILL])assert.match(A.toolAvail(id),/locked/);});
test('topology tools disabled in Animate while deformation and appearance remain available',()=>{layer();A.S.mode='animate';for(const id of ['pen','freehand','drawshape','deleteedge','eraser','createshape','deleteshape','reduce'])assert.ok(A.toolAvail(id));for(const id of ['points','pointtf','curvature','magnet','shear','bend','noise','linewidth','hideedge','exposure','colorpoints'])assert.equal(A.toolAvail(id),null);});
test('geometry can exist without any shape',()=>{const L=layer();A.S.newStyle.fillOn=false;A.S.newStyle.strokeOn=false;path(L,[[0,0],[100,0]]);assert.equal(L.shapes.length,0);assert.equal(L.paths.length,1);A.vectorRunAction('createshape');assert.equal(L.shapes.length,0);A.S.newStyle.strokeOn=true;A.vectorRunAction('createshape');assert.equal(L.shapes.length,1);A.S.newStyle.fillOn=true;});
test('split inserts midpoint and preserves a cubic',()=>{const L=layer(),p=path(L,[[0,0,1],[50,80,1],[150,20,1],[200,100,1]]),P=A.vectorPathPoints(L),before=A.vectorCubic(L,p,1,P,0);A.S.selPts=new Set([p.pts[1],p.pts[2]]);A.vectorRunAction('split');assert.equal(p.pts.length,5);for(let i=0;i<=20;i++){const t=i/20,q=A.vectorCubic(L,p,t<=.5?1:2,A.vectorPathPoints(L),0);point(A.vectorBezier(before,t),A.vectorBezier(q,t<=.5?t*2:(t-.5)*2));}});
test('weld crossing curves shares a single real point',()=>{const L=layer(),p=path(L,[[0,0],[100,100]]),q=path(L,[[0,100],[100,0]]);A.S.selPts.clear();assert.equal(A.vectorWeldCrossings(L),1);assert.equal(p.pts.length,3);assert.equal(q.pts.length,3);assert.equal(p.pts[1],q.pts[1]);point([L.pts[p.pts[1]].x,L.pts[p.pts[1]].y],[50,50]);});
test('selection groups store IDs and Delete preserves points',()=>{const L=layer(),p=path(L,[[0,0],[20,0]]);A.VEC.groupName='Hand';A.vectorRunAction('groupcreate');assert.equal(L.pointGroups[0].name,'Hand');assert.equal(L.pointGroups[0].points.join(','),p.pts.join(','));A.vectorRunAction('groupdelete');assert.equal(L.pointGroups.length,0);assert.equal(Object.keys(L.pts).length,2);});
test('simplification reduces a straight path and removes orphan keys',()=>{const L=layer(),p=path(L,Array.from({length:20},(_,i)=>[i*10,0]));A.setVal(L,'pv:'+p.pts[5]+':width',2,10,true);A.vectorSimplify(L,50);assert.equal(p.pts.length,2);assert.equal(Object.keys(L.ch).length,0);});
test('delete edge opens a closed curve without deleting its shape',()=>{const L=layer(),p=path(L,[[0,0],[100,0],[100,100],[0,100]],true),ids=[...p.pts];A.vectorDeleteEdge(L,p,1);assert.equal(p.closed,false);assert.equal(p.pts.length,4);assert.equal(p.pts[0],ids[2]);assert.equal(L.shapes.length,1);});
