test('Bézier handles draw and drag without moving the point',()=>{const L=layer(),p=path(L,[[0,0,1],[100,0,1],[100,100,1]]);A.S.selPts=new Set([p.pts[1]]);A.VEC.handles=true;A.VEC.fixed=true;const h=A.vectorHandles(L).find(h=>h.side==='hout');down('pointtf',...h.p);assert.equal(A.Stage.drag.mode,'handle');move('pointtf',h.p[0]+10,h.p[1]+20);up('pointtf');point([L.pts[p.pts[1]].x,L.pts[p.pts[1]].y],[100,0]);assert.ok(L.pts[p.pts[1]].hout);assert.equal(A.H.undo.length,1);});
